import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC 0091 — libSQL/sqld as the SQLite driver","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0091-libsql-sqld-driver.md"},"headers":[],"relativePath":"rfcs/0091-libsql-sqld-driver.md","filePath":"rfcs/0091-libsql-sqld-driver.md"}'),s={name:"rfcs/0091-libsql-sqld-driver.md"};function i(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="rfc-0091-—-libsql-sqld-as-the-sqlite-driver" tabindex="-1">RFC 0091 — libSQL/<code>sqld</code> as the SQLite driver <a class="header-anchor" href="#rfc-0091-—-libsql-sqld-as-the-sqlite-driver" aria-label="Permalink to &quot;RFC 0091 — libSQL/`sqld` as the SQLite driver&quot;">​</a></h1><p><strong>Status:</strong> Implemented — workstream 0009&#39;s all 4 legs are done; <code>sqld</code> is now baked into the base Docker Compose files as the mandatory SQLite driver<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> Claude Code (workstream 0009 leg 2 spike, for kasunben)<br><strong>Scope:</strong> <code>packages/db</code>, <code>docker-compose.yml</code>, <code>docker-compose.prod.yml</code>; supersedes <a href="./../research/0003-horizontal-scaling-strategy.html">research 0003</a>&#39;s SQLite recommendation<br><strong>Incorporated into plan:</strong> Yes — the encryption-carve-out recommendation was approved via merge of <a href="https://github.com/sovereignfs/sovereign/pull/364" target="_blank" rel="noreferrer">PR #364</a>, which served as its review/sign-off vehicle. Workstream 0009 leg 3 (<code>packages/db</code> driver swap) is unblocked.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Workstream 0009 locked a decision to make <code>sqld</code> (libSQL&#39;s server) mandatory for every SQLite-dialect Sovereign instance, replacing direct <code>better-sqlite3</code> file access, staged across legs 2–4. This RFC is leg 2&#39;s deliverable: it reports what a live spike against <code>sqld</code> actually found, and proposes a design for all four of the questions leg 2 was asked to resolve — including the encryption question, which turned out to be a genuine blocker rather than an engineering judgment call.</p><p><strong>The short version:</strong> the async-contract concern research 0003 raised is real but narrower than feared — 9 call sites, not a rewrite. The deployment shape is straightforward and already stood up. <code>sqld</code>&#39;s server-side encryption-at-rest, however, has been an open, unresolved upstream issue for roughly two years, and where any encryption-at-rest capability exists in the libSQL ecosystem today it&#39;s explicitly documented as experimental and unsuitable for production data. Adopting <code>sqld</code> unconditionally would silently remove the guarantee RFC 0071 was built to provide, for the one plugin that actually depends on it — HealthLog, per the <a href="./../incidents/2026-07-24-rfc-0071-encryption-rollout.html">RFC 0071 incident doc</a>. This RFC&#39;s recommendation is a narrow <strong>encryption carve-out</strong>: everything that RFC 0071 would encrypt today stays on plain-file SQLite + SQLCipher; everything else moves to <code>sqld</code>. It&#39;s a security-guarantee tradeoff, so it&#39;s flagged for kasunben&#39;s explicit decision rather than treated as settled by this document alone — see Proposed design and Alternatives considered.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Workstream 0009 leg 2 exists specifically to answer two questions research 0003 left open before any production code depends on the answer:</p><ol><li>How does libSQL&#39;s client — async even for local access — reconcile with <code>packages/db</code>&#39;s dialect-agnostic async contract?</li><li>How does RFC 0071&#39;s SQLCipher-based at-rest encryption map onto a <code>sqld</code>-backed database?</li></ol><p>Plus two things the workstream doc flagged as needing a concrete decision: the driver shape itself, and embedded-replica vs. remote-only deployment.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><code>packages/db/src/dialect.ts:1</code> — <code>Dialect = &#39;sqlite&#39; | &#39;postgres&#39;</code>, resolved from <code>DB_DIALECT</code>/<code>DATABASE_URL</code> (<code>resolveDialect()</code>, <code>dialect.ts:20</code>).</li><li><code>packages/db/src/client.ts</code> and <code>packages/db/src/plugin-client.ts</code> open SQLite via <code>drizzle-orm/better-sqlite3</code> directly against a local file (<code>resolveSqlitePath()</code>), synchronously.</li><li><code>packages/db/src/sqlite-encryption.ts:314</code> — <code>openKeyedSqlite()</code>, described in its own comment as &quot;the single chokepoint every SQLite call site in this package (and its self-contained <code>apps/auth</code> twin) uses.&quot; It calls SQLCipher-specific pragmas (<code>cipher=&#39;sqlcipher&#39;</code>, <code>sqlite.key(key)</code>) directly against a <code>better-sqlite3-multiple-ciphers</code> <code>Database</code> instance — raw driver API, not something Drizzle&#39;s query builder touches.</li><li><code>docs/architecture-rules.md:42-47</code> — &quot;The platform data layer is async... On SQLite the underlying better-sqlite3 calls still run synchronously; the async signature is the dialect-agnostic contract. Never reintroduce a synchronous platform-DB read.&quot; Every platform-level caller (<code>getPlatformDb()</code>, <code>sdk.platform.getConfig()</code>, etc.) already <code>await</code>s regardless of dialect.</li><li>Despite that rule, <code>packages/db/src/platform-db.ts</code> has <strong>7</strong> call sites and <code>scripts/seed.ts</code> has <strong>2</strong> that use SQLite-specific <em>synchronous</em> driver APIs inside dialect branches — Drizzle&#39;s sync-only <code>.all()</code>/<code>.get()</code>/<code>.run()</code> (only available on the <code>better-sqlite3</code> adapter) in <code>platform-db.ts</code>, and raw <code>db.prepare(sql).get()</code> (bypassing Drizzle entirely) in <code>seed.ts</code>. Full list: <code>platform-db.ts:172,186,211,250,273,312,349</code>; <code>seed.ts:149,156</code>.</li><li>RFC 0071&#39;s own text: Postgres already has a documented, weaker fallback — &quot;no SQLCipher equivalent — falls back to disk + <code>sslmode</code>,&quot; with a startup <strong>warning</strong> (not an enforced failure) when a <code>requireEncryption</code> plugin resolves to Postgres. This is the existing precedent for &quot;this dialect can&#39;t give the real guarantee.&quot;</li><li>CLAUDE.md&#39;s own standing note: RFC 0071&#39;s encryption surface &quot;has an above-average bug surface — treat it as still-settling, not hardened,&quot; with three separate hardening passes so far including a production incident.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="deployment-shape-—-resolved" tabindex="-1">Deployment shape — resolved <a class="header-anchor" href="#deployment-shape-—-resolved" aria-label="Permalink to &quot;Deployment shape — resolved&quot;">​</a></h3><p><code>sqld</code> lives in its own overlay file, <code>docker-compose.sqld.yml</code>, mirroring the existing <code>docker-compose.postgres.yml</code> pattern rather than being embedded in the base compose files — internal-only (no host port), reached by service name, a <code>/health</code>-backed healthcheck matching <code>postgres</code>&#39;s <code>pg_isready</code> one. <code>docker compose up</code> is unchanged for every existing deployment; the overlay is opt-in by construction (nobody gets it without the extra <code>-f</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker compose -f docker-compose.prod.yml -f docker-compose.sqld.yml up --build -d</span></span></code></pre></div><p>Image: <code>ghcr.io/tursodatabase/libsql-server:latest</code>. Config used in the spike: <code>SQLD_NODE=primary</code>, default HTTP (<code>0.0.0.0:8080</code>) and gRPC (<code>0.0.0.0:5001</code>) listeners, data at <code>/var/lib/sqld</code> inside the container, backed by a dedicated <code>sovereign_sqld_data</code> named volume — deliberately separate from <code>sovereign_data</code>, since <code>sqld</code>&#39;s on-disk format isn&#39;t a set of <code>.db</code> files the existing backup/restore tooling understands.</p><p><strong>Unlike <code>docker-compose.postgres.yml</code>, this overlay doesn&#39;t yet override <code>runtime</code>/<code>auth</code>&#39;s connection settings</strong> — there&#39;s no driver in <code>packages/db</code> that consumes an <code>sqld</code> URL yet (that&#39;s leg 3). It only stands the service up for prototyping directly. Once leg 3 ships, expect this overlay&#39;s shape to change: <code>sqld</code> is meant to become mandatory whenever <code>DB_DIALECT=sqlite</code> (workstream 0009&#39;s locked decision), not an opt-in alternative the way Postgres is — so its service definition most likely folds into the base <code>docker-compose.yml</code>/<code>.prod.yml</code> directly at that point, rather than staying behind a separate overlay. <code>docker-compose.postgres.yml</code> remains the real &quot;switch away from the default dialect&quot; file either way.</p><p><strong>Embedded replica vs. remote-only:</strong> primary-only. Nothing in Sovereign&#39;s design calls for a remote/edge replica — there is exactly one <code>sqld</code> instance per deployment, reached only by that deployment&#39;s own <code>runtime</code>/<code>auth</code> containers over the internal Docker network. Embedded-replica mode exists to sync a local read replica from a <em>remote</em> primary (e.g. Turso Cloud); that doesn&#39;t describe this topology. Settled by default; revisit only if leg 3 surfaces a concrete need.</p><p><strong>Auth:</strong> not yet decided. <code>sqld</code> supports HTTP basic (<code>SQLD_HTTP_AUTH</code>) or JWT (<code>SQLD_AUTH_JWT_KEY</code>/<code>_FILE</code>). The spike ran with neither, relying on the Docker network being unreachable from the host. Leg 3 should decide whether network isolation alone is sufficient (mirroring how Postgres is typically deployed in this stack today) or whether <code>sqld</code> should also require its own credential — flagged for leg 3, not blocking this RFC.</p><h3 id="driver-shape-—-resolved" tabindex="-1">Driver shape — resolved <a class="header-anchor" href="#driver-shape-—-resolved" aria-label="Permalink to &quot;Driver shape — resolved&quot;">​</a></h3><p><code>Dialect</code> stays <code>&#39;sqlite&#39; | &#39;postgres&#39;</code> — <strong>no third literal.</strong> Since workstream 0009 already locked &quot;mandatory, no per-plugin override,&quot; there is no remaining case where the platform needs to distinguish &quot;plain-file SQLite&quot; from &quot;<code>sqld</code>-backed SQLite&quot; at the type level. <code>DB_DIALECT=sqlite</code> continues to mean what it means today from the operator&#39;s perspective; only the connection URL scheme changes (<code>file:./data/sovereign.db</code> → an <code>http://sqld:8080</code>-style service URL) and the driver underneath changes (<code>drizzle-orm/better-sqlite3</code> → <code>drizzle-orm/libsql</code> + <code>@libsql/client</code>). This is a smaller footprint than research 0003 assumed when it treated <code>sqld</code> as an &quot;opt-in third dialect path.&quot;</p><p>Call sites: <code>packages/db/src/client.ts</code> (platform DB) and <code>plugin-client.ts</code> (<code>getPluginDb</code>, <code>provisionPluginDb</code>, <code>dropPluginDb</code>) swap their <code>sqlite</code> branch&#39;s driver construction. <code>apps/auth/src/db.ts</code> needs the equivalent change — it duplicates the SQLite-opening logic deliberately (<code>architecture-rules.md:51</code>, &quot;auth does not depend on <code>packages/db</code>&quot;).</p><h3 id="async-contract-migration-—-resolved-smaller-than-feared" tabindex="-1">Async-contract migration — resolved, smaller than feared <a class="header-anchor" href="#async-contract-migration-—-resolved-smaller-than-feared" aria-label="Permalink to &quot;Async-contract migration — resolved, smaller than feared&quot;">​</a></h3><p>Confirmed empirically (live spike against the running <code>sqld</code> container, <code>@libsql/client@0.15</code>): <code>.execute()</code>, <code>.transaction()</code>, and <code>.batch()</code> all return Promises unconditionally — there is no synchronous fast path, unlike <code>better-sqlite3</code>.</p><p>This is <strong>not</strong> the platform-wide rewrite research 0003 worried about. The public platform-data-layer contract is already async-signatured on every dialect (<code>architecture-rules.md:42-47</code>) — callers everywhere already <code>await</code>. The actual work is the 9 call sites listed under Current State: convert <code>platform-db.ts</code>&#39;s 7 dialect-branched <code>.all()</code>/<code>.get()</code>/<code>.run()</code> calls to <code>await</code>-based Drizzle calls (mirroring the existing Postgres branch immediately next to each one — the pattern to copy already exists in the same file), and rewrite <code>seed.ts</code>&#39;s 2 raw <code>db.prepare(sql).get()</code> calls to <code>await client.execute(sql)</code>. Comparable in size to a single focused PR, not &quot;comparable to the existing per-dialect schema duplication&quot; as research 0003 estimated.</p><h3 id="encryption-at-rest-—-recommended-a-carve-out-scoped-to-rfc-0071-s-existing-boundary" tabindex="-1">Encryption-at-rest — recommended: a carve-out scoped to RFC 0071&#39;s existing boundary <a class="header-anchor" href="#encryption-at-rest-—-recommended-a-carve-out-scoped-to-rfc-0071-s-existing-boundary" aria-label="Permalink to &quot;Encryption-at-rest — recommended: a carve-out scoped to RFC 0071&#39;s existing boundary&quot;">​</a></h3><p><strong>Recommendation:</strong> move to <code>sqld</code> everywhere RFC 0071 would <strong>not</strong> apply encryption today; keep plain-file SQLite + SQLCipher everywhere it <strong>would</strong>. Reuse RFC 0071&#39;s own existing boundary rather than inventing a new one:</p><ul><li>The platform DB (<code>sovereign.db</code>) and <code>apps/auth</code>&#39;s DB (<code>auth.db</code>) stay on plain-file SQLite whenever the operator has <code>SOVEREIGN_DB_ENCRYPTION_KEY</code> set at all — that env var is the instance-wide encryption toggle, and moving those two databases to <code>sqld</code> would silently drop the guarantee for <em>every</em> operator who turned it on, not only <code>requireEncryption</code> plugin authors.</li><li>Any isolated plugin database stays on plain-file SQLite whenever that plugin&#39;s manifest declares <code>database.requireEncryption: true</code> — the <strong>raise-only</strong> semantics from task 8.15 are unaffected: a plugin can still never be <em>forced</em> onto <code>sqld</code> against a real encryption requirement it declared, regardless of what the platform&#39;s own dialect otherwise is.</li><li>Everything else — the platform/auth DBs when no key is set, and every plugin database that never asked for encryption — moves to <code>sqld</code>.</li></ul><p>This is not the workstream&#39;s original &quot;mandatory, no exceptions&quot; as written — it&#39;s <code>resolvePluginDialect()</code>&#39;s removed per-plugin override (leg 1) coming back in a much narrower, principled form: not &quot;any plugin can pick any dialect for any reason&quot; (arbitrary, ungoverned, unused by any of the 12 shipped manifests — exactly why leg 1 removed it), but &quot;a database that has a real, already-validated encryption requirement keeps the one mechanism that satisfies it.&quot; The condition is a single existing boolean this codebase already checks (<code>resolvePluginEncryptionKey</code>/<code>checkEncryptionMarker</code>, <code>packages/db/src/sqlite-encryption.ts</code>), not new per-plugin flexibility.</p><p><strong>Follow-up spike: does <code>sqld</code>&#39;s encryption actually work?</strong> Built <code>libsql-server</code> locally from source with <code>--build-arg ENABLE_FEATURES=encryption</code> (the Dockerfile already has this arg; no upstream code change needed) and tested it directly rather than relying on the &quot;experimental&quot; label alone:</p><ul><li>Startup banner correctly reports <code>encryption at rest: enabled</code> when <code>SQLD_ENCRYPTION_KEY</code> is set.</li><li>Wrote a canary string through the client, confirmed round-trip read, then restarted the container with the <strong>same</strong> key — data read back correctly. Restarted with the <strong>wrong</strong> key — <code>sqld</code> refused to start with a clear <code>Error code 26: File opened that is not a database file</code>, rather than serving garbage or corrupting anything. Fails safely.</li><li>Searched every file on disk (binary-safe <code>grep -a</code>, since a naive <code>grep</code> silently skips files it detects as binary — a real methodology bug this spike caught by cross-checking against a plaintext baseline, which showed the canary present in <code>data-wal</code>/<code>wallog</code> when unencrypted, and absent from every file — including those same <code>data-wal</code>/<code>wallog</code> — when encrypted). The canary and shorter substrings of it were genuinely absent everywhere in the encrypted case.</li></ul><p><strong>So the feature is not broken for the basic case</strong> — mechanically, a single key set once, no rekeying, no <code>bottomless</code> S3 replication, works correctly and fails safely. This softens &quot;no viable equivalent&quot; from the earlier draft: it&#39;s not vaporware. But it doesn&#39;t overturn the carve-out recommendation, for three reasons that don&#39;t require the feature to be broken:</p><ol><li><strong>No published image ships it.</strong> Using it means building and maintaining our own <code>libsql-server</code> image from source with a non-default Cargo feature, tracking upstream releases ourselves — real, ongoing operational cost, not a one-time flip.</li><li><strong>No HMAC.</strong> The cipher is <code>Aes256Cbc</code> with no message authentication (<code>libsql-sys/src/connection.rs</code>) — unlike SQLCipher, which authenticates by default. This is a permanent design property, not something that matures with time.</li><li><strong>This spike is not a security audit.</strong> One afternoon of black-box testing against the single-key case is not the bar RFC 0071 was held to (three hardening passes, a production incident, ongoing scrutiny). Treating a quick &quot;it round-trips&quot; as equivalent confidence would undersell exactly the caution CLAUDE.md asks for in this area.</li></ol><p><strong>Cost, stated plainly:</strong> <code>packages/db</code>&#39;s SQLite path keeps two drivers (<code>better-sqlite3-multiple-ciphers</code> for the encrypted case, <code>@libsql/client</code> for everything else) instead of fully retiring <code>better-sqlite3</code>. That&#39;s real, ongoing duplication — some of exactly what this workstream set out to remove — carried specifically because RFC 0071&#39;s guarantee has cost three hardening passes and a production incident to earn, and this RFC is not willing to spend that for a <code>sqld</code> feature with a ~2-year-open upstream issue and no committed timeline. The carve-out is explicitly revisitable: once <code>sqld</code>&#39;s encryption-at-rest matures (issue #1756 closes and the fix ships stable, not just merges), a follow-up leg can retire the <code>better-sqlite3</code> path entirely.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Keep plain-file SQLite</strong> — already rejected; workstream 0009 locked &quot;mandatory, staged&quot; over &quot;opt-in third tier&quot; in the design session that produced it. Not re-litigated here.</li><li><strong>rqlite, a bespoke SQLite server</strong> — already rejected in research 0003 (no Drizzle driver / reinventing what libSQL solves). Not re-litigated here.</li><li><strong>Turso&#39;s from-scratch Rust rewrite (&quot;Turso&quot; the database, distinct from libSQL)</strong> — rejected for now. Per Turso&#39;s own co-founder: &quot;Turso is a new SQLite-compatible database, rewritten from scratch in Rust, currently in beta... we&#39;re actively working towards adding Turso to it [Turso Cloud].&quot; libSQL/<code>sqld</code> is what actually powers Turso Cloud in production today; the newer rewrite is explicitly the vendor&#39;s stated long-term direction but is earlier-stage than <code>sqld</code> itself. Worth tracking as a future migration risk — today&#39;s adoption target may itself be superseded eventually — but adopting the <em>less</em> mature of the two available options to hedge against that would be backwards.</li><li><strong>Wait for upstream before starting leg 3 at all.</strong> Track issue #1756, block every part of the migration — not just the encrypted case — until it closes. Rejected: the issue has been open ~2 years with no visible progress, and this would hold the async-contract and driver-shape work (both fully resolved, see above) hostage to a dateless external timeline for no reason — those parts don&#39;t touch encryption at all.</li><li><strong>Self-build a <code>sqld</code> image with <code>--build-arg ENABLE_FEATURES=encryption</code> instead of a carve-out</strong>, using the confirmed-working feature from the spike above for every database, encrypted or not — no <code>better-sqlite3</code> path at all. Rejected for now: this trades a self-contained, well-tested dependency (<code>better-sqlite3-multiple-ciphers</code>, already in the Docker image, already hardened over three passes) for an unpublished custom build we&#39;d own the maintenance of, using a no-HMAC cipher, validated by one afternoon of black-box testing rather than a real audit. Worth revisiting once <code>sqld</code> ships this in a published image and it&#39;s had real production exposure elsewhere — not something to build our own supply chain around today.</li><li><strong>Accept a guarantee downgrade instead of a carve-out</strong>, matching Postgres&#39;s existing &quot;disk + operator-managed encryption, startup warning&quot; precedent for every SQLite database, encrypted or not. Rejected: this is a real regression for HealthLog specifically — from &quot;the platform refuses to run without a key&quot; to &quot;the platform warns and proceeds anyway&quot; — traded away only to avoid a driver-duplication cost this RFC considers acceptable given RFC 0071&#39;s own track record (three hardening passes, one production incident) of being worth extra care.</li><li><strong>Reopen mandatory-vs-opt-in itself</strong>, closer to research 0003&#39;s original &quot;opt-in third tier&quot; recommendation — plain-file SQLite stays available as a general escape hatch, not just for the encrypted case. Rejected as broader than the actual gap: the async-contract and deployment-shape questions are fully resolved and don&#39;t need an opt-out; only the encryption boundary does, and the carve-out already covers exactly that boundary without reopening workstream 0009&#39;s mandatory decision for everything else.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><code>sqld</code> auth model for the internal Docker network (see Deployment shape above) — leg 3&#39;s call, not this RFC&#39;s.</li><li>Timeline for retiring the carve-out once <code>sqld</code>&#39;s encryption-at-rest matures — not urgent; revisit when issue #1756 actually closes, not on a schedule.</li><li>Whether to post this spike&#39;s findings (the working build flag, the round-trip and wrong-key results) as a comment on <a href="https://github.com/tursodatabase/libsql/issues/1756" target="_blank" rel="noreferrer">tursodatabase/libsql#1756</a>. Independent of the carve-out decision — this is &quot;share a reproduction that might help an idle upstream issue,&quot; not something blocking or blocked by leg 3.</li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p><strong>Approved via merge of PR #364.</strong> Leg 3 implements the driver swap (<code>client.ts</code>, <code>plugin-client.ts</code>, <code>apps/auth/src/db.ts</code>, the 9 async-contract call sites, per-dialect schema files under <code>packages/db/src/schema/</code>) with the carve-out&#39;s boundary condition (current key/<code>requireEncryption</code> state) built in from the start, not bolted on after. Leg 4 remains the one-time data cutover for the single production instance, excluding whichever databases the carve-out keeps on plain-file SQLite.</p><p>No published-package semver impact — <code>packages/db</code> and <code>apps/auth</code> are both private, unpublished packages.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft from workstream 0009 leg 2&#39;s live spike against <code>sqld</code> 0.24.33.</td></tr><tr><td>0.2</td><td>August 2026</td><td>Added an explicit recommendation for the encryption question: a carve-out scoped to RFC 0071&#39;s existing key/<code>requireEncryption</code> boundary. Still needs kasunben&#39;s sign-off — a security-guarantee tradeoff, not an engineering call this RFC finalizes alone.</td></tr><tr><td>0.3</td><td>August 2026</td><td>Follow-up spike: built <code>libsql-server</code> from source with <code>--build-arg ENABLE_FEATURES=encryption</code> and tested it directly. The feature works correctly for the basic single-key case (round-trips, fails safely on a wrong key, no plaintext leakage in the main file, WAL, or replication log) — softens &quot;no viable equivalent&quot; to &quot;no published/audited equivalent.&quot; Carve-out recommendation unchanged; added self-built-image as a considered-and-rejected alternative.</td></tr></tbody></table>',44)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
